parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "intencion": {
      "type": "string",
      "enum": [
        "PEDIDO_MUDANZA",
        "CONSULTA_COMERCIAL",
        "RECLAMO",
        "FUERA_DE_AMBITO",
        "DUDOSA"
      ]
    },
    "nombre": {
      "type": "string"
    },
    "apellido": {
      "type": "string"
    },
    "telefono": {
      "type": "string"
    },
    "datos_pedido": {
      "type": "object",
      "properties": {
        "origen": {
          "type": "string"
        },
        "destino": {
          "type": "string"
        },
        "fecha_mudanza": {
          "type": "string"
        },
        "objetos_especiales": {
          "type": "string"
        },
        "ambientes": {
          "type": "string",
          "description": "Solo el número de ambientes contando el living (\"2 dormitorios\" = \"3\"), o \"no informado\""
        }
      },
      "required": [
        "origen",
        "destino",
        "ambientes",
        "fecha_mudanza",
        "objetos_especiales"
      ]
    },
    "calificacion": {
      "type": "string",
      "enum": [
        "caliente",
        "tibio",
        "frio",
        "no_aplica"
      ]
    },
    "resumen": {
      "type": "object",
      "properties": {
        "asunto_principal": {
          "type": "string"
        },
        "puntos_clave": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "minItems": 1,
          "maxItems": 5
        },
        "accion_requerida": {
          "type": "string"
        }
      },
      "required": [
        "asunto_principal",
        "puntos_clave",
        "accion_requerida"
      ]
    },
    "respuesta_borrador": {
      "type": "string"
    }
  },
  "required": [
    "intencion",
    "nombre",
    "apellido",
    "telefono",
    "datos_pedido",
    "calificacion",
    "resumen",
    "respuesta_borrador"
  ]
}
